[ExtensionOf(tableStr(PurchAgreementHeaderHistory))]
final public class AVAPurchAgreementHeaderHistoryDbt_Extension
{
}

Method.Source:
public void insert()
{
    next insert();

    PurchAgreementHeaderHistory::avaCopyMarkup(this.avaGetPurchAgreementHeader(), this);
}

/// <summary>
/// Copies markup records from origin to destination record
/// </summary>
/// <param name = "_fromHeader">Common - normally PurchAgreementHeader</param>
/// <param name = "_toHeader">Common - normally PurchAgreementHeaderHistory</param>
public static void avaCopyMarkup(Common _fromHeader, Common _toHeader)
{
    Markup::copy(NoYes::No, _fromHeader, _toHeader);
}

/// <summary>
/// Gets related PurchAgreementHeader record
/// </summary>
/// <returns>PurchAgreementHeader</returns>
public PurchAgreementHeader avaGetPurchAgreementHeader()
{
    return PurchAgreementHeader::find(this.AgreementHeader);
}

/// <summary>
/// Finds <c>PurchAgreementHeaderHistory</c> record
/// </summary>
/// <param name = "_recId">RecId</param>
/// <param name = "_selectForUpdate">boolean</param>
/// <returns>PurchAgreementHeaderHistory</returns>
public static PurchAgreementHeaderHistory avaFindRecId(RecId _recId, boolean _selectForUpdate = false)
{
    PurchAgreementHeaderHistory avaHeaderHistory;

    if(_selectForUpdate)
    {
        avaHeaderHistory.selectForUpdate(_selectForUpdate);
    }

    select firstonly avaHeaderHistory
        where avaHeaderHistory.RecId == _recId;

    return avaHeaderHistory;
}
